    <script>
        const clients = JSON.parse(document.getElementById('clients-data').textContent); const products = JSON.parse(document.getElementById('products-data').textContent); const clientSearch = document.getElementById('client-search'); const productSearch = document.getElementById('product-search'); let selectedProducts = [];
        const selectClient = () => { const value = clientSearch.value.toLowerCase(); const client = clients.find((item) => item.name.toLowerCase() === value || String(item.ruc_ci || '').toLowerCase() === value); if (!client) return; document.getElementById('client_id').value = client.id; document.getElementById('customer_ruc_ci').value = client.ruc_ci || ''; document.getElementById('customer_address').value = client.address || ''; document.getElementById('customer_phone').value = client.phone || ''; const label = document.getElementById('selected-client'); label.textContent = `${client.name} | RUC/CI: ${client.ruc_ci || '-'} | ${client.address || '-'} | ${client.phone || '-'}`; label.classList.remove('hidden'); };
        const findProduct = () => { const value = productSearch.value.toLowerCase(); return products.find((item) => item.name.toLowerCase() === value || String(item.id) === value); };
        const syncTotals = () => { const quantity = Number(document.getElementById('quantity').value || 0); const price = Number(document.getElementById('unit_price').value || 0); const subtotal = quantity * price; const tax = subtotal * Number(document.querySelector('[data-iva]').dataset.iva) / 100; document.getElementById('preview-subtotal').textContent = '$' + subtotal.toFixed(2); document.getElementById('preview-tax').textContent = '$' + tax.toFixed(2); document.getElementById('preview-grand-total').textContent = '$' + (subtotal + tax).toFixed(2); };
        const renderProducts = () => { const body = document.getElementById('product-lines'); body.innerHTML = selectedProducts.length ? selectedProducts.map((item, index) => `<tr><td class="p-3">${index + 1}</td><td class="p-3"><input data-field="cpc" value="${item.cpc}" class="w-28 rounded border border-[#dce5df] px-2 py-1"></td><td class="p-3"><input value="${item.description}" readonly class="w-64 cursor-not-allowed rounded border border-[#edf1ee] bg-[#f3f5f4] px-2 py-1 text-[#687a72]"></td><td class="p-3"><input value="${item.unit}" readonly class="w-24 cursor-not-allowed rounded border border-[#edf1ee] bg-[#f3f5f4] px-2 py-1 text-[#687a72]"></td><td class="p-3"><input data-field="quantity" type="number" min="1" value="${item.quantity}" class="w-20 rounded border border-[#dce5df] px-2 py-1"></td><td class="p-3"><input value="${item.price}" readonly class="w-28 cursor-not-allowed rounded border border-[#edf1ee] bg-[#f3f5f4] px-2 py-1 text-[#687a72]"></td><td data-line-total class="p-3">$${(item.quantity * item.price).toFixed(2)}</td><td class="p-3"><button type="button" data-remove="${index}" class="rounded bg-[#dc2626] px-3 py-1.5 text-xs font-semibold text-white shadow-sm hover:bg-[#b91c1c]">Eliminar</button></td></tr>`).join('') : '<tr><td colspan="8" class="p-6 text-center text-sm text-[#789086]">Aun no hay productos seleccionados.</td></tr>'; body.querySelectorAll('[data-remove]').forEach((button) => button.addEventListener('click', () => { selectedProducts.splice(Number(button.dataset.remove), 1); syncForm(); renderProducts(); })); body.querySelectorAll('[data-field]').forEach((input) => input.addEventListener('input', (event) => { const row = event.target.closest('tr'); const index = [...body.querySelectorAll('tr')].indexOf(row); selectedProducts[index][event.target.dataset.field] = Number(event.target.value) || 0; row.querySelector('[data-line-total]').textContent = '$' + (selectedProducts[index].quantity * selectedProducts[index].price).toFixed(2); syncForm(); })); };
        const syncForm = () => { const item = selectedProducts[0]; if (!item) return; document.getElementById('product_code').value = item.cpc; document.getElementById('product_description').value = item.description; document.getElementById('unit').value = item.unit; document.getElementById('quantity').value = item.quantity; document.getElementById('unit_price').value = item.price; syncTotals(); };
        clientSearch.addEventListener('change', selectClient); document.getElementById('add-product').addEventListener('click', () => { const product = findProduct(); if (!product) return; selectedProducts.push({ cpc: '', description: product.name, unit: 'UNIDAD', quantity: 1, price: product.price || 0 }); productSearch.value = ''; document.getElementById('selected-product').textContent = `${product.name} seleccionado. Completa el CPC y la cantidad en la tabla.`; syncForm(); renderProducts(); });
    </script>
    <section class="overflow-hidden rounded-2xl border border-[#dce5df] bg-white shadow-sm"><div class="border-b border-[#edf1ee] p-5"><span class="text-sm text-[#789086]">{{ $proformas->count() }} proformas registradas</span></div><div class="overflow-x-auto"><table class="w-full min-w-[950px] text-left text-sm"><thead class="bg-[#f8faf9] text-xs uppercase tracking-wider text-[#789086]"><tr><th class="px-5 py-4">Numero</th><th class="px-5 py-4">Cliente</th><th class="px-5 py-4">Fecha</th><th class="px-5 py-4">Total</th><th class="px-5 py-4">Estado</th><th class="px-5 py-4">Documento</th></tr></thead><tbody class="divide-y divide-[#edf1ee]">@forelse($proformas as $proforma)<tr><td class="px-5 py-4 font-semibold text-[#52752b]">{{ $proforma->number }}</td><td class="px-5 py-4">{{ $proforma->client?->name ?? 'Sin cliente' }}</td><td class="px-5 py-4 text-[#6d8077]">{{ $proforma->quote_date?->format('d/m/Y') }}</td><td class="px-5 py-4 font-semibold">$ {{ number_format($proforma->total, 2, ',', '.') }}</td><td class="px-5 py-4">{{ ucfirst($proforma->status) }}</td><td class="px-5 py-4"><a href="{{ route('proformas.print', $proforma) }}" target="_blank" class="text-xs font-semibold text-[#52752b]">Ver / imprimir</a></td></tr>@empty<tr><td colspan="6" class="p-10 text-center text-sm text-[#789086]">No hay proformas. Crea la primera.</td></tr>@endforelse</tbody></table></div></section>
